using Dates, JSON3, OrderedCollections

version = JSON3.read(read(download("https://api.github.com/repos/mdn/browser-compat-data/releases/latest"))).name

path = download("https://github.com/mdn/browser-compat-data/releases/download/$version/data.json")

obj = JSON3.read(read(path));

#-----------------------------------------------------------------------------# ELEMENTS
ELEMENTS = OrderedDict{Symbol, @NamedTuple{attributes::Vector{Symbol}, deprecated::Bool, experimental::Bool, standard_track::Bool}}()
GLOBAL_ATTRIBUTES = Tuple(keys(obj.html.global_attributes))
ATTRIBUTES = OrderedDict{Symbol, Any}()

for (k, v) in obj.html.elements
    (; deprecated, experimental, standard_track) = v.__compat.status
    ELEMENTS[k] = (; attributes = Symbol[], deprecated, experimental, standard_track)

    for (attr, attr_v) in v
        attr == :__compat && continue
        (; deprecated, experimental, standard_track) = attr_v.__compat.status
        ATTRIBUTES[attr] = (; deprecated, experimental, standard_track)
        push!(ELEMENTS[k].attributes, attr)
    end
end

open(joinpath(@__DIR__, "..", "src", "generated.jl"), "w") do io
    println(io, """
    # This file was generated by deps/generate.jl at $(Dates.now())
    # Do not edit it manually

    const GLOBAL_ATTRIBUTES = $GLOBAL_ATTRIBUTES

    const ATTRIBUTES = OrderedDict(
        $(join(pairs(ATTRIBUTES), ",\n    "))
    )

    const ELEMENTS = OrderedDict(
        $(join(pairs(ELEMENTS), ",\n    "))
    )

    """)
end
